import sys
import json

sysin = json.loads(sys.stdin.read() or "null")

base = sysin.get("base")
files = sysin.get("files") or []

out = dict(base or {})

for f in files:
    pc = (f or {}).get("problemCounts") or {}
    for k, v in pc.items():
        try:
            n = int(v)
        except Exception:
            continue
        if n <= 0:
            continue
        out[k] = out.get(k, 0) + n

result = out

print(json.dumps(result, ensure_ascii=False))

import sys
import json

sysin = json.loads(sys.stdin.read() or "null")

items = sysin.get("items") or []
category = sysin.get("category")

def _sum_for_category(d):
    out = 0
    for k, v in (d or {}).items():
        try:
            n = int(v)
        except Exception:
            continue
        if n <= 0:
            continue
        if k == category:
            out += n
    return out

files_total = 0
for f in items:
    pc = (f or {}).get("problemCounts")
    files_total += _sum_for_category(pc)

result = files_total

print(json.dumps(result, ensure_ascii=False))

import sys
import json

sysin = json.loads(sys.stdin.read() or "null")

files = sysin.get("files") or []
category = sysin.get("category")
fallback_total = sysin.get("fallbackTotal", 5)

def _sum_for_category(d):
    out = 0
    for k, v in (d or {}).items():
        try:
            n = int(v)
        except Exception:
            continue
        if n <= 0:
            continue
        if k == category:
            out += n
    return out

total = 0
for f in files:
    pc = (f or {}).get("problemCounts")
    total += _sum_for_category(pc)

if total <= 0:
    total = fallback_total

result = total

print(json.dumps(result, ensure_ascii=False))
